const g = (n) => $(n).first().json.text || '';
const text = [
  '# ⚡ Tu mes de Reels',
  '# 1 · Ideas', g('Cadena · Ideas'),
  '# 2 · Guiones de las 3 mejores ideas', g('Cadena · Guiones'),
  '# 3 · Trial Reels de la idea 1', g('Cadena · Trial Reels'),
  '# 4 · Calendario de la semana', g('Cadena · Calendario'),
].join('\n\n');
return [{ json: { text } }];

const md = $input.first().json;
const body = md.html || '';
const page = `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
body{font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;max-width:900px;margin:32px auto;padding:0 16px;line-height:1.55;color:#1d1d1f;background:#fff}
h1,h2,h3{line-height:1.25}h2{border-bottom:2px solid #eee;padding-bottom:6px;margin-top:32px}
table{border-collapse:collapse;width:100%;font-size:14px;display:block;overflow-x:auto}
th,td{border:1px solid #ddd;padding:8px;text-align:left;vertical-align:top}th{background:#f5f5f7}
code,pre{background:#f5f5f7;border-radius:6px}pre{padding:12px;overflow-x:auto;white-space:pre-wrap}
.bar{position:sticky;top:0;background:#fff;padding:8px 0;text-align:right}
button{padding:8px 14px;border-radius:8px;border:1px solid #ccc;background:#fff;cursor:pointer}
@media print{.bar{display:none}}
</style></head><body><div class="bar"><button onclick="navigator.clipboard.writeText(document.getElementById('md').textContent)">Copiar Markdown</button> <button onclick="print()">Imprimir / PDF</button></div>
${body}<pre id="md" style="display:none">${(md.text||'').replace(/</g,'&lt;')}</pre></body></html>`;
return [{ json: { page } }];

// El modelo devuelve el HTML del lead magnet; quitamos posibles ```html ... ```
let t = $input.first().json.text || '';
const m = t.match(/```(?:html)?\s*([\s\S]*?)```/i);
if (m) t = m[1];
if (!/<html/i.test(t)) t = `<!doctype html><html><head><meta charset="utf-8"></head><body><pre style="white-space:pre-wrap">${t.replace(/</g,'&lt;')}</pre></body></html>`;
return [{ json: { page: t } }];
